mapper.select:
SELECT * FROM comment
WHERE parent_id = #{parentId}
ORDER BY comment_time ASC
    LIMIT #{offset}, #{limit}

mapper.update:
UPDATE comment
SET
    status = -1
WHERE comment_id = #{commentId}
   OR parent_id = #{commentId}

UPDATE comment
SET
    child_count = child_count + #{delta}
WHERE comment_id = #{commentId}

UPDATE comment
SET
   like_count = like_count + #{delta}
WHERE comment_id = #{commentId}

